"""Standalone local report: all candidate state quantities and storyboard figures."""
from pathlib import Path
import json
R=Path(__file__).parent
items=[json.loads(p.read_text()) for p in sorted((R/'data/states').glob('x*.json'))]
html=r'''<!doctype html><meta charset="utf-8"><title>Compact fire-state storyboards</title><style>body{font:16px system-ui;margin:30px auto;max-width:1500px;padding:0 20px;color:#24313d;background:#f6f7f8}h1{font-size:30px}section{background:white;padding:22px;margin:18px 0;border-radius:12px}select,input{font:inherit;margin:8px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{text-align:left;padding:8px;border-bottom:1px solid #ddd;vertical-align:top}th{background:#edf2f4}.note{background:#fff3dc;padding:16px;border-radius:8px}img{width:100%}.grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}pre{white-space:pre-wrap}small{color:#526370}@media(max-width:900px){.grid{display:block}}</style>
<h1>What a compact fire state would contain</h1><p>Measured FDS data, not model predictions. Local preparation only: no fitting or new simulations.</p>
<div class="note">A candidate state, not a validated sufficient state. Temperature-weighted geometry is a lossy plume summary. Heat release (kW), stored thermal energy (J), and heat flux (kW/m²) are different quantities. Thermal energy in joules and separate remaining water/dry-fuel/char masses are unavailable in this extraction.</div>
<section><label>Simulation <select id="cases"></select></label><label>Saved snapshot <input id="time" type="range" min="0" max="90" value="15"><b id="timelabel"></b></label><p id="conditions"></p><p id="splits"></p></section>
<section><h2>Fire storyboard</h2><p>Orange arrow: crown centre to hot-gas centroid, in metres. Orange ellipse: 2σ temperature-weighted extent in the x–z view, not a flame boundary or a confidence interval. Blue arrow: ambient wind, with 1 plotted metre per m/s. All panels use the same spatial scale.</p><img id="board"><p id="boardnote"></p></section>
<div class="grid"><section><h2>Dynamic gas and plume quantities</h2><table id="gas"></table></section><section><h2>Derived 3-D shape and motion</h2><table id="shape"></table><p>Null means no active region, not a zero-length flame. HOT = gas temperature >50°C; plume moments weight those cells by T−20°C. HRR moments use nonnegative saved gas HRR density. Covariance is retained in 3-D; the storyboard collapses y.</p></section></div>
<section><h2>Dynamic vegetation quantities — all four classes</h2><p>Temperature, diameter and heat flux summaries are weighted by represented particle mass. These are summaries, not full material distributions; distributions may be needed for a sufficient next-state model. Positive/negative heat-flux signs are preserved from FDS.</p><table id="material"></table><p id="alignment"></p></section>
<section><h2>Static properties and external forcing</h2><table id="static"></table><p>Tree geometry and initial moisture are fixed conditions. Ambient wind is a supplied boundary condition; this model proposal does not forecast weather. The imposed ignition source is 1500°C for20s. Its on/off indicator is a command, not a measured heat-transfer rate.</p></section>
<section><h2>Unavailable or not yet justified</h2><ul><li>Separate remaining dry fuel, liquid water and char: not explicitly captured by these particle channels.</li><li>Gas thermal energy in joules: requires appropriate density, composition and heat capacity; temperature-volume integral is only a proxy.</li><li>Directional radiative flux onto another tree: integrated gas radiation intensity is not that quantity.</li><li>Proof that this compact state predicts its own future: requires one-step and self-fed rollout tests.</li></ul><p>Generic3m-wide conical crowns4/6/8/10m tall above2m,1600weighted particles,0.5m grid,24×16×16m domain,180s. No trunks, buildings or embers. These are simulated gas/material histories, not physical validation.</p></section>
<section><h2>Data provenance</h2><p>48 previously used development histories (8 training and40 validation trajectories),91 snapshots each. All 48 histories have storyboards. The eight training histories were strength-stratified; this is not a new test set. No new test cases decoded. All archived bundles SHA256-checked; scalar states retain original times and particle units.</p><pre id="provenance"></pre></section>
<script>const DATA=__DATA__;
const el=id=>document.getElementById(id), fmt=v=>v===null?'Unavailable / inactive':typeof v==='number'?Number(v.toPrecision(6)):JSON.stringify(v);
function table(id,rows){el(id).innerHTML='<tr><th>Quantity</th><th>Value</th></tr>'+rows.map(([k,v])=>'<tr><td>'+k+'</td><td>'+fmt(v)+'</td></tr>').join('')}
DATA.forEach((x,i)=>{let o=document.createElement('option');o.value=i;o.text=x.case+' | '+x.conditions.crown_height_m+'m | wind '+x.conditions.wind_speed+'m/s | moisture '+x.conditions.moisture;el('cases').add(o)});
function draw(){let x=DATA[+el('cases').value],c=x.conditions,r=x.snapshots[+el('time').value];el('timelabel').textContent=r.time_s.toFixed(3)+' s';el('conditions').textContent='Crown '+c.crown_height_m+' m; wind '+c.wind_speed+' m/s (+X); initial moisture '+100*c.moisture+'% dry basis; loading ×'+c.loading_multiplier+'; ignition angle '+c.angle_deg+'°';el('splits').textContent='Existing '+c.split+' history; configuration '+c.configuration+'; replica '+c.replica+'. Split labels retained for provenance, not new model selection.';
el('board').style.display='block';el('board').src='storyboards/'+x.case+'.png';el('boardnote').textContent='Twelve panels at 2, 4, 8, 16, 20, 32, 48, 64, 72, 76, 78 and 90 seconds (nearest saved timestamps shown). The imposed source switches off at 20 seconds. Numeric controls retain all 91 snapshots through 180 seconds.';
table('gas',[['Gas HRR from saved cells (kW)',r.gas_HRR_kW],['Global HRR CSV (kW)',r.global_HRR_kW],['Solid oxidation HRR CSV (kW)',r.solid_oxidation_HRR_kW],['Fuel-vapour release (kg/s)',r.fuel_vapor_release_kg_s],['HOT volume (m³)',r.hot_volume_m3],['Peak gas T (°C)',r.peak_gas_temperature_C],['Positive temperature-excess volume integral (K m³), NOT joules',r.temperature_excess_integral_K_m3],['Whole-volume mean radiation intensity (kW/m²)',r.mean_radiation_intensity],['Maximum radiation intensity (kW/m²)',r.max_radiation_intensity],['Remaining total material mass (kg)',r.remaining_total_material_mass_kg]]);
table('shape',[['HOT centroid xyz (m)',r.hot_plume?.centroid_m??null],['HOT covariance3×3 (m²)',r.hot_plume?.covariance_m2??null],['HOT RMS radius (m)',r.hot_plume?.rms_radius_m??null],['Crown→HOT centroid displacement xyz (m)',r.plume_displacement_from_crown_m],['HOT-weighted gas velocity xyz (m/s)',r.hot_weighted_velocity_m_s],['HRR-weighted centroid xyz (m)',r.hrr_region?.centroid_m??null],['HRR covariance3×3 (m²)',r.hrr_region?.covariance_m2??null]]);
el('material').innerHTML='<tr><th>Class</th><th>Total mass kg</th><th>T °C</th><th>Diameter μm</th><th>Incident flux kW/m²</th><th>Convective flux kW/m²</th><th>Particles</th></tr>'+r.material_classes.map(v=>'<tr>'+[v.class_name,v.remaining_total_mass_kg,v.mass_weighted['PARTICLE TEMPERATURE'],v.mass_weighted['PARTICLE DIAMETER'],v.mass_weighted['INCIDENT HEAT FLUX'],v.mass_weighted['PARTICLE CONVECTIVE HEAT FLUX'],v.particle_count].map(z=>'<td>'+fmt(z)+'</td>').join('')+'</tr>').join('');
el('alignment').textContent='Particle timestamp '+r.particle_time_s.toFixed(4)+'s; alignment difference '+r.alignment_error_s.toFixed(4)+'s. Particle weighting factors were applied to all mass totals; class counts are not physical leaf counts.';
table('static',[['Crown height m',c.crown_height_m],['Crown width m',3],['Crown base height m',2],['Ambient wind xyz m/s',[c.wind_speed,0,0]],['Initial moisture dry-basis fraction',c.moisture],['Loading multiplier',c.loading_multiplier],['Ignition angle degrees',c.angle_deg],['Imposed igniter on',r.igniter_command_on],['Realization seed (provenance, not physical state)',c.seed]]);el('provenance').textContent='Raw archive SHA256: '+x.raw_sha256+'\nFull machine-readable state: states/'+x.case+'.json';}
el('cases').onchange=draw;el('time').oninput=draw;draw();</script>'''
(R/'data/report.html').write_text(html.replace('__DATA__',json.dumps(items,allow_nan=False)))
print('REPORT',len(items))
